181	
182	    public List<Pet> getPets() {
183	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
184	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
185	        return Collections.unmodifiableList(sortedPets);
