1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Assigns the {@code customerCode} formatted {@code <CITY3>-<LAST3>-<NNNN>}, where CITY3 is the
9	 * upper-cased first three letters of the city, LAST3 the upper-cased first three letters of the last
10	 * name, and NNNN a per-city 4-digit zero-padded sequence equal to one more than the number of owners
11	 * already in that city.
12	 */
13	public class AssignCustomerCode {
14	
15	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
16	        String city = owner.getCity();
17	        String city3 = prefix(city);
18	        String last3 = prefix(owner.getLastName());
19	        int sequence = countInCity(ownerRepository, city) + 1;
20	        owner.setCustomerCode(String.format("%s-%s-%04d", city3, last3, sequence));
21	    }
22	
23	    /** Upper-cased first three letters of {@code value}. */
24	    private static String prefix(String value) {
25	        String s = value == null ? "" : value;
26	        return s.substring(0, Math.min(3, s.length())).toUpperCase();
27	    }
28	
29	    /** Number of existing owners in the same city, compared case-insensitively. */
30	    private static int countInCity(OwnerRepository ownerRepository, String city) {
31	        int count = 0;
32	        for (Owner existing : ownerRepository.findAll()) {
33	            if (city == null ? existing.getCity() == null : city.equalsIgnoreCase(existing.getCity())) {
34	                count++;
35	            }
36	        }
37	        return count;
38	    }
39	}
40

