3	/**
4	 * Thrown when a request to create an owner would exceed the per-day create limit: the maximum number
5	 * of owners registered today (by {@code registrationDate}) has already been reached, so the request is
6	 * answered with a 429 Too Many Requests rather than exceeding the daily cap. Carries the limit so
7	 * {@link DailyLimitExceededExceptionHandler} can report it. Checked so it appears in the function's
8	 * {@code throws} clause and is routed as an escalation.
9	 */
10	public class DailyLimitExceededException extends Exception {
11	
12	    private final int limit;
13	
14	    public DailyLimitExceededException(int limit) {
15	        super("The maximum of " + limit + " owners have already been created today");
16	        this.limit = limit;
17	    }
18	
19	    public int getLimit() {
20	        return this.limit;
21	    }
22	}
